// Validate YAML content in the corpus files with the `yaml` package (YAML 1.2, strict).
// Usage: node validate.js <file>...
const fs = require('fs');
const path = require('path');
const YAML = require('yaml');

function check(label, src) {
  const docs = YAML.parseAllDocuments(src, { version: '1.2', strict: true, uniqueKeys: true, prettyErrors: true });
  const list = Array.isArray(docs) ? docs : [docs];
  let ok = true;
  list.forEach((d, i) => {
    for (const e of d.errors) { ok = false; console.log(`  ERROR ${label} doc#${i}: ${e.message.split('\n')[0]}`); }
    for (const w of d.warnings) { console.log(`  warn  ${label} doc#${i}: ${w.message.split('\n')[0]}`); }
  });
  return { ok, n: list.length };
}

function hashpipeBlocks(text, prefixRe) {
  const lines = text.split(/\r?\n/);
  const blocks = [];
  let cur = null;
  lines.forEach((ln, i) => {
    const m = ln.match(prefixRe);
    if (m) {
      if (!cur) { cur = { start: i + 1, lines: [] }; blocks.push(cur); }
      cur.lines.push(m[1].replace(/^ /, ''));
    } else cur = null;
  });
  return blocks;
}

for (const f of process.argv.slice(2)) {
  let text = fs.readFileSync(f, 'utf8');
  if (text.charCodeAt(0) === 0xfeff) text = text.slice(1);
  const ext = path.extname(f).toLowerCase();
  const name = path.basename(f);
  if (ext === '.yml' || ext === '.yaml') {
    const r = check(name, text);
    console.log(`${r.ok ? 'OK ' : 'BAD'} ${name}: ${r.n} document(s)`);
    continue;
  }
  let results = [];
  if (['.md', '.qmd', '.rmd'].includes(ext)) {
    const fm = text.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n/);
    if (fm) results.push(['front matter', check(name + ' front matter', fm[1])]);
    const fenceRe = /^(`{3,})\s*\{?(yaml|yml)\b[^\n]*\n([\s\S]*?)^\1\s*$/gm;
    let m;
    while ((m = fenceRe.exec(text))) {
      const line = text.slice(0, m.index).split('\n').length;
      results.push([`yaml fence @${line}`, check(`${name} yaml fence @${line}`, m[3])]);
    }
    for (const b of hashpipeBlocks(text, /^#\|(.*)$/)) results.push([`#| @${b.start}`, check(`${name} #| @${b.start}`, b.lines.join('\n'))]);
    for (const b of hashpipeBlocks(text, /^%%\|(.*)$/)) results.push([`%%| @${b.start}`, check(`${name} %%| @${b.start}`, b.lines.join('\n'))]);
  } else {
    for (const b of hashpipeBlocks(text, /^\s*#\|(.*)$/)) results.push([`#| @${b.start}`, check(`${name} #| @${b.start}`, b.lines.join('\n'))]);
  }
  const bad = results.filter(([, r]) => !r.ok);
  console.log(`${bad.length ? 'BAD' : 'OK '} ${name}: ${results.length} YAML region(s) [${results.map(([l]) => l).join(', ')}]`);
}

