            }
            Kind::Seq(items) => {
                for it in items {
                    walk(&it.value, out);
                }
            }
            _ => {}
        }
    }
    let mut out = Vec::new();
    for doc in &stream.docs {
        if let Some(r) = &doc.root {
            walk(r, &mut out);
        }
    }
    out
}

